"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0db/refs"
import { cn } from "@/lib/utils"
import { Row, RowKind, RowMeta, RowTitle, Rows } from "@/components/ui/rows"

type SwapyItem = {
  id: string
  /** The row's name. It is also what a screen reader hears as the row moves. */
  label: string
  /** What it is, in graphite. */
  kind?: React.ReactNode
  /** The quiet fact at the end: a length, a year. */
  meta?: React.ReactNode
}

type SwapyProps = Omit<React.ComponentProps<"div">, "children" | "defaultValue"> & {
  /** Names the list: "Running order". */
  label: string
  items: readonly SwapyItem[]
  /** The ids in order. Ids missing from it keep their place at the end. */
  order?: readonly string[]
  defaultOrder?: readonly string[]
  onOrderChange?: (order: string[]) => void
  /**
   * default: the row you hold reverses out of ink and travels with your hand. transpose: the proofreader's
   * transposition mark, a loop in the margin from where the row was to where it is, and the held name in italic.
   */
  variant?: "default" | "transpose"
  disabled?: boolean
  /** Starts with this row picked up, as if its move word had just been pressed. */
  defaultHeld?: string
}

/** The given order, without ids that are gone, then any new ids at the end. */
function reconcile(order: readonly string[], ids: string[]) {
  const known = new Set(ids)
  const kept = order.filter((id) => known.has(id))
  const seen = new Set(kept)
  return [...kept, ...ids.filter((id) => !seen.has(id))]
}

const place = (n: number) => String(n + 1).padStart(2, "0")

/**
 * Rows you put in order by hand. Each row's "move" word is its handle: press it and the row is held (it reverses
 * out of ink), the arrow keys carry it up and down, and pressing again sets it down; Escape puts it back. Or drag
 * the word. Rows glide to their new places, their numbers turn over, and every move is said aloud.
 */
function Swapy({
  label,
  items,
  order,
  defaultOrder = [],
  onOrderChange,
  variant = "default",
  disabled = false,
  defaultHeld,
  className,
  ref: forwardedRef,
  ...props
}: SwapyProps) {
  const [local, setLocal] = React.useState<readonly string[]>(defaultOrder)
  const ids = reconcile(order ?? local, items.map((item) => item.id))
  const byId = new Map(items.map((item) => [item.id, item]))
  const [held, setHeld] = React.useState<string | null>(defaultHeld ?? null)
  const [origin, setOrigin] = React.useState(() => (defaultHeld ? ids.indexOf(defaultHeld) : -1))
  const [said, setSaid] = React.useState("")
  const [dragging, setDragging] = React.useState(false)
  const drag = React.useRef<{ id: string; pointer: number; moved: boolean; wasHeld: boolean } | null>(null)
  const root = React.useRef<HTMLDivElement>(null)
  const composedRef = useComposedRefs(root, forwardedRef)
  const list = React.useRef<HTMLUListElement>(null)
  const arc = React.useRef<SVGSVGElement>(null)
  const was = React.useRef(new Map<string, { top: number; at: number }>())
  const hint = React.useId()
  const n = ids.length
  const name = (id: string) => byId.get(id)?.label ?? id

  const commit = (next: string[]) => {
    if (order === undefined) setLocal(next)
    onOrderChange?.(next)
  }
  const moveTo = (id: string, to: number) => {
    const at = ids.indexOf(id)
    const end = Math.min(Math.max(to, 0), n - 1)
    if (at < 0 || end === at) return false
    const next = ids.filter((x) => x !== id)
    next.splice(end, 0, id)
    commit(next)
    setSaid(`${name(id)}, ${end + 1} of ${n}.`)
    return true
  }
  const lift = (id: string) => {
    setHeld(id)
    setOrigin(ids.indexOf(id))
    setSaid(`${name(id)} picked up, ${ids.indexOf(id) + 1} of ${n}.`)
  }
  const setDown = (id: string) => {
    setHeld(null)
    setSaid(`${name(id)} set down, ${ids.indexOf(id) + 1} of ${n}.`)
  }
  const putBack = (id: string) => {
    moveTo(id, origin)
    setHeld(null)
    setSaid(`${name(id)} put back, ${origin + 1} of ${n}.`)
  }

  /** Which place the pointer is over, read from the layout (not the gliding rows) so nothing jitters. */
  const slotAt = (y: number) => {
    const ul = list.current
    if (!ul) return -1
    const top = ul.getBoundingClientRect().top
    const lis = Array.from(ul.children) as HTMLElement[]
    for (let i = 0; i < lis.length; i++) if (y < top + lis[i].offsetTop + lis[i].offsetHeight) return i
    return lis.length - 1
  }

  // After every render: rows that changed place glide there (FLIP), and their numbers turn over the way they went.
  React.useLayoutEffect(() => {
    const ul = list.current
    if (!ul) return
    const still = matchMedia("(prefers-reduced-motion: reduce)").matches
    const cs = getComputedStyle(ul)
    const glide = { duration: parseFloat(cs.getPropertyValue("--db-moderato")) || 320, easing: cs.getPropertyValue("--db-breath").trim() || "ease" }
    const turn = { duration: glide.duration, easing: cs.getPropertyValue("--db-exhale").trim() || "ease-out" }
    const seen = new Map<string, { top: number; at: number }>()
    Array.from(ul.children).forEach((li, at) => {
      if (!(li instanceof HTMLElement)) return
      const id = li.dataset.id ?? ""
      const before = was.current.get(id)
      seen.set(id, { top: li.offsetTop, at })
      if (still || !before) return
      if (before.top !== li.offsetTop) li.animate([{ translate: `0 ${before.top - li.offsetTop}px` }, { translate: "0 0" }], glide)
      // ponytail: only the new figure turns in; the old one isn't kept to turn out, since React has already written the new one.
      const fig = li.querySelector<HTMLElement>(".db-swap-n")
      if (fig && before.at !== at) fig.animate([{ opacity: 0, translate: `0 ${at > before.at ? "0.6em" : "-0.6em"}` }, { opacity: 1, translate: "0 0" }], turn)
    })
    was.current = seen

    // transpose: the loop runs in the margin from the place the row was picked up to the place it's in now.
    const svg = arc.current
    if (!svg || !held || origin < 0) return
    const lis = Array.from(ul.children) as HTMLElement[]
    const mid = (li?: HTMLElement) => (li ? ul.offsetTop + li.offsetTop + li.offsetHeight / 2 : 0)
    const now = ids.indexOf(held)
    if (now === origin) return
    const y0 = mid(lis[origin])
    const y1 = mid(lis[now])
    const w = svg.clientWidth - 6 // the ends stop short of the numbers
    svg.querySelector("path")?.setAttribute("d", `M ${w} ${y0} C ${-w * 0.33} ${y0} ${-w * 0.33} ${y1} ${w} ${y1}`)
    svg.querySelector("circle")?.setAttribute("cx", String(w))
    svg.querySelector("circle")?.setAttribute("cy", String(y1))
    root.current?.style.setProperty("--db-swap-mid", `${(y0 + y1) / 2}px`)
  })

  const looped = variant === "transpose" && held !== null && origin >= 0 && ids.indexOf(held) !== origin

  return (
    <div
      ref={composedRef}
      data-slot="swapy"
      data-variant={variant === "default" ? undefined : variant}
      data-holding={held ? "" : undefined}
      data-dragging={dragging || undefined}
      data-disabled={disabled || undefined}
      className={cn("db-swap", className)}
      {...props}
    >
      <Rows ref={list} aria-label={label}>
        {ids.map((id, at) => {
          const item = byId.get(id)
          if (!item) return null
          const mine = held === id
          return (
            <Row key={id} data-id={id} data-held={mine || undefined}>
              <span className="db-swap-n" aria-hidden="true">{place(at)}</span>
              <RowTitle>{item.label}</RowTitle>
              {item.kind != null ? <RowKind>{item.kind}</RowKind> : null}
              {item.meta != null ? <RowMeta>{item.meta}</RowMeta> : null}
              <button
                type="button"
                data-slot="swapy-move"
                className="db-swap-move"
                aria-label={`Move ${item.label}, ${at + 1} of ${n}`}
                aria-pressed={mine}
                aria-describedby={hint}
                disabled={disabled || n < 2}
                onPointerDown={(e) => {
                  if (e.button !== 0 || disabled) return
                  e.preventDefault() // no text selection; focus by hand instead
                  e.currentTarget.focus({ focusVisible: false } as FocusOptions)
                  e.currentTarget.setPointerCapture(e.pointerId)
                  drag.current = { id, pointer: e.pointerId, moved: false, wasHeld: mine }
                  setDragging(true)
                  if (!mine) lift(id)
                }}
                onPointerMove={(e) => {
                  const d = drag.current
                  if (!d || d.pointer !== e.pointerId) return
                  if (moveTo(d.id, slotAt(e.clientY))) d.moved = true
                }}
                onPointerUp={(e) => {
                  const d = drag.current
                  if (!d || d.pointer !== e.pointerId) return
                  drag.current = null
                  setDragging(false)
                  // A drag sets the row down where it's let go; a plain press picks it up, and a second press sets it down.
                  if (d.moved || d.wasHeld) setDown(d.id)
                }}
                onPointerCancel={() => {
                  if (drag.current) setDown(drag.current.id)
                  drag.current = null
                  setDragging(false)
                }}
                onClick={(e) => {
                  if (e.detail !== 0) return // the pointer already did it; this is Enter or Space
                  if (mine) setDown(id)
                  else lift(id)
                }}
                onKeyDown={(e) => {
                  const to = { ArrowUp: at - 1, ArrowDown: at + 1, Home: 0, End: n - 1 }[e.key]
                  if (to !== undefined) {
                    e.preventDefault()
                    if (!mine) lift(id)
                    moveTo(id, to)
                  } else if (e.key === "Escape" && mine) {
                    e.preventDefault()
                    putBack(id)
                  }
                }}
                onBlur={(e) => {
                  // Moving a row can blur it for a moment while React reinserts it; only a real departure sets it down.
                  const el = e.currentTarget
                  requestAnimationFrame(() => {
                    if (mine && !drag.current && document.activeElement !== el) setDown(id)
                  })
                }}
              >
                <span data-word="move">move</span>
                <span data-word="moving">moving</span>
                <span className="db-swap-arrow" aria-hidden="true">↕</span>
              </button>
            </Row>
          )
        })}
      </Rows>
      {variant === "transpose" ? (
        <>
          <svg ref={arc} className="db-swap-arc" data-shown={looped || undefined} aria-hidden="true">
            <path />
            <circle r="3.5" />
          </svg>
          <span className="db-swap-tr" data-shown={looped || undefined} aria-hidden="true">tr</span>
        </>
      ) : null}
      <p id={hint} className="db-sr">Press to pick the row up, then the arrow keys to move it, and press again to set it down. Escape puts it back.</p>
      <p role="status" className="db-sr">{said}</p>
    </div>
  )
}

export { Swapy, type SwapyProps, type SwapyItem }

@layer components {
  /* ── db-swap ── rows you put in order by hand, after "the uncreative": the row you hold reverses out of an ink block and
     travels with your hand. A "move" word is the handle. Borrows db-rows for the hairlines, the title and the columns. */
  .db-swap { position: relative; container-type: inline-size; }
  .db-swap .db-rows { position: relative; }
  .db-swap .db-rows > li { position: relative; }
  .db-swap .db-rows .db-rows-link { grid-template-columns: auto minmax(0, 1fr); }
  .db-swap .db-rows .db-rows-link::after { content: none; } /* nothing opens, so no arrow and no room kept for one */
  .db-swap .db-rows-link > * { transition: color var(--db-allegro), translate var(--db-moderato) var(--db-exhale); }
  .db-swap .db-rows-title { line-height: calc(var(--db-mf) * var(--db-mf-lh)); transition: color var(--db-allegro), translate var(--db-moderato) var(--db-exhale), font-weight var(--db-moderato) var(--db-breath), letter-spacing var(--db-moderato) var(--db-breath); }
  /* The place, a number used as data: it turns over as the row moves. Figures always read left to right. */
  .db-swap-n { min-inline-size: 2ch; font-size: var(--db-pp); color: var(--db-pencil); font-variant-numeric: tabular-nums; direction: ltr; unicode-bidi: isolate; }

  /* The handle is a word, and the arrow says which way it goes. Both words share one cell, so the row never reflows. */
  .db-swap-move {
    display: inline-grid; grid-template-columns: auto auto; column-gap: 0.3em; align-items: baseline;
    appearance: none; border: 0; background: none; margin: calc(-1 * var(--db-space-3)) calc(-1 * var(--db-space-2)); padding: var(--db-space-3) var(--db-space-2);
    font: inherit; color: var(--db-graphite); cursor: grab; touch-action: none; user-select: none; -webkit-user-select: none;
    transition: color var(--db-allegro);
  }
  .db-swap-move > [data-word] { grid-area: 1 / 1; }
  .db-swap-move > [data-word="moving"], .db-swap-move[aria-pressed="true"] > [data-word="move"] { visibility: hidden; }
  .db-swap-move[aria-pressed="true"] > [data-word="moving"] { visibility: visible; }
  .db-swap-arrow { grid-area: 1 / 2; color: var(--db-pencil); display: inline-block; transition: color var(--db-allegro), translate var(--db-moderato) var(--db-spiccato); }
  .db-swap-move:is(:hover, :focus-visible), .db-swap[data-force~="hover"] > .db-rows > li:first-child .db-swap-move { color: var(--db-ink); }
  .db-swap-move:is(:hover, :focus-visible) .db-swap-arrow, .db-swap[data-force~="hover"] > .db-rows > li:first-child .db-swap-arrow { color: var(--db-ink); translate: 0 -0.08em; }
  .db-swap[data-dragging], .db-swap[data-dragging] .db-swap-move { cursor: grabbing; }

  /* Held: an ink block prints across the row from the inline start and the words reverse to paper; the name steps
     forward and sets heavier and tighter, as the poster's reversed word does. */
  .db-swap:not([data-variant]) .db-rows-link::before {
    content: ""; position: absolute; inset: 0 calc(-1 * var(--db-space-3)); z-index: -1;
    background: var(--db-ink); scale: 0 1; transform-origin: 0 50%;
    transition: scale var(--db-moderato) var(--db-exhale);
  }
  :is([dir="rtl"], [dir="rtl"] *) .db-swap:not([data-variant]) .db-rows-link::before { transform-origin: 100% 50%; }
  .db-swap .db-rows > li[data-held] { z-index: 1; }
  .db-swap:not([data-variant]) li[data-held] .db-rows-link::before { scale: 1 1; }
  .db-swap:not([data-variant]) li[data-held] .db-rows-link > *, .db-swap:not([data-variant]) li[data-held] .db-swap-arrow { color: var(--db-paper); }
  .db-swap li[data-held] .db-rows-title { translate: var(--step) 0; }
  .db-swap:not([data-variant]) li[data-held] .db-rows-title { font-weight: 560; letter-spacing: -0.035em; }
  .db-swap:not([data-variant]) li[data-held] .db-swap-move:focus-visible { outline-color: var(--db-paper); }

  /* Narrow: the names step down a size and the kind gives way, so a name never runs into its neighbours. */
  @container (max-width: 30rem) {
    .db-swap .db-rows .db-rows-link { column-gap: var(--db-space-4); }
    .db-swap .db-rows-title { font-size: var(--db-mp); line-height: calc(var(--db-mp) * var(--db-mp-lh)); letter-spacing: var(--db-mp-tr); overflow-wrap: break-word; }
    .db-swap[data-variant="transpose"] .db-rows li[data-held] .db-rows-title { font-size: var(--db-mp); } /* no lift here, so the name keeps its one line */
    .db-swap .db-rows-kind { display: none; }
  }

  .db-swap[data-disabled] :is(.db-rows-title, .db-rows-kind, .db-swap-move, .db-swap-arrow) { color: var(--db-pencil); }
  .db-swap-move:disabled { cursor: default; }

  /* ── transpose ── the proofreader's transposition mark. No ink: the held name turns italic (yours now) and the rest step
     back to pencil; a hairline loop in the margin runs from the place it was picked up to the place it is, ending in a dot,
     with "tr" written by it. Set down, the mark fades: the correction is made. */
  .db-swap[data-variant="transpose"] { --db-swap-margin: var(--db-space-7); padding-inline-start: var(--db-swap-margin); }
  .db-swap[data-variant="transpose"][data-holding] li:not([data-held]) .db-rows-link > :is(.db-rows-title, .db-rows-kind) { color: var(--db-pencil); }
  .db-swap[data-variant="transpose"] li[data-held] .db-rows-title { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * var(--db-mf)); letter-spacing: 0; }
  .db-swap-arc {
    position: absolute; inset-block-start: 0; inset-inline-start: calc(var(--db-swap-margin) - var(--db-space-5)); inline-size: var(--db-space-5); block-size: 100%;
    overflow: visible; pointer-events: none; opacity: 0; transition: opacity var(--db-moderato) var(--db-breath);
  }
  .db-swap-arc path { fill: none; stroke: var(--db-ink); stroke-width: var(--db-hairline); }
  .db-swap-arc circle { fill: var(--db-ink); }
  :is([dir="rtl"], [dir="rtl"] *) .db-swap-arc { scale: -1 1; }
  .db-swap-tr {
    position: absolute; inset-inline-end: calc(100% - var(--db-swap-margin) + var(--db-space-5) + var(--db-space-2)); inset-block-start: var(--db-swap-mid, 0); translate: 0 -50%; pointer-events: none;
    font: italic 400 calc(var(--db-expression-scale) * var(--db-p)) / 1 var(--db-expression); color: var(--db-pencil);
    opacity: 0; transition: opacity var(--db-moderato) var(--db-breath);
  }
  .db-swap :is(.db-swap-arc, .db-swap-tr)[data-shown] { opacity: 1; }
  @media (max-width: 40rem) { .db-swap[data-variant="transpose"] { --db-swap-margin: var(--db-space-6); } .db-swap-tr { font-size: var(--db-pp); } }

  @media (forced-colors: active) {
    .db-swap:not([data-variant]) li[data-held] .db-rows-link::before { background: Highlight; forced-color-adjust: none; }
    .db-swap:not([data-variant]) li[data-held] .db-rows-link > *, .db-swap:not([data-variant]) li[data-held] .db-swap-arrow { color: HighlightText; forced-color-adjust: none; }
    .db-swap-arc path { stroke: CanvasText; } .db-swap-arc circle { fill: CanvasText; }
  }
}
